<?php
require_once __DIR__.'/config/auth.php'; require_role('admin','teacher');
$me=current_user();$id=(int)($_GET['id']??0);
$sql="SELECT s.*,g.group_name,t.full_name teacher_name FROM class_sessions s JOIN student_groups g ON g.id=s.group_id JOIN users t ON t.id=s.teacher_id WHERE s.id=?";$args=[$id];if($me['role']==='teacher'){$sql.=' AND s.teacher_id=?';$args[]=$me['id'];}
$st=$pdo->prepare($sql);$st->execute($args);$session=$st->fetch();if(!$session){http_response_code(404);exit('Дарс ёфт нашуд.');}
$st=$pdo->prepare("SELECT u.id,u.full_name,u.student_code,a.scanned_at,a.status,a.source,a.note FROM users u LEFT JOIN attendance a ON a.student_id=u.id AND a.class_session_id=? WHERE u.role='student' AND u.group_id=? ORDER BY u.full_name");$st->execute([$id,$session['group_id']]);$rows=$st->fetchAll();
$present=count(array_filter($rows,fn($r)=>in_array($r['status']??'', ['present','late'], true)));$excused=count(array_filter($rows,fn($r)=>($r['status']??'')==='excused'));$absent=count($rows)-$present-$excused;$pageTitle='Ҳисоботи пурраи дарс';require __DIR__.'/partials/header.php';
?>
<div class="content-card"><div class="section-heading"><div><span class="status-pill <?=$session['status']==='active'?'active':'closed'?>"><?=$session['status']==='active'?'Фаъол':'Анҷом ёфт'?></span><h3 class="mt-2"><?=e($session['lesson_title'])?></h3><p><?=e($session['group_name'])?> · <?=e($session['teacher_name'])?> · <?=e($session['started_at'])?></p></div><a class="btn btn-outline-success" href="export_session_csv.php?id=<?=$id?>">Боргирии CSV</a></div>
<div class="stats-grid"><div class="stat-card"><span>Ҳамаи донишҷӯён</span><strong><?=count($rows)?></strong></div><div class="stat-card"><span>Ҳозир</span><strong><?=$present?></strong></div><div class="stat-card"><span>Ғоиб</span><strong><?=$absent?></strong></div><div class="stat-card"><span>Узрнок</span><strong><?=$excused?></strong></div><div class="stat-card"><span>Фоизи ҳозиршавӣ</span><strong><?=count($rows)? round($present/count($rows)*100,1):0?>%</strong></div></div>
<div class="table-responsive mt-4"><table class="table modern-table"><thead><tr><th>№</th><th>Донишҷӯ</th><th>Рамз</th><th>Ҳолат</th><th>Вақт</th><th>Манбаъ</th><th>Шарҳ</th></tr></thead><tbody><?php foreach($rows as $i=>$r):?><tr><td><?=$i+1?></td><td><?=e($r['full_name'])?></td><td><?=e($r['student_code'])?></td><td><?php if(!$r['scanned_at']):?><span class="status-pill closed">Ғоиб</span><?php else:?><span class="status-pill active"><?= $r['status']==='late'?'Дер омад':($r['status']==='excused'?'Узрнок':'Ҳозир') ?></span><?php endif;?></td><td><?=e($r['scanned_at']??'—')?></td><td><?=($r['source']??'')==='manual'?'Дастӣ':'QR'?></td><td><?=e($r['note']??'—')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="text-center">Дар ин гурӯҳ донишҷӯ сабт нашудааст.</td></tr><?php endif;?></tbody></table></div></div>
<?php require __DIR__.'/partials/footer.php'; ?>
